window.FILM_WORK_PROMPTS={"work_id":"src-da0a57939468ad5f","records":[{"work_id":"src-da0a57939468ad5f","frame_id":"FG-a880c4691effddae","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1243).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"画面主体为覆盖着红色斑驳液体的大面积起伏表面，左上角可见黑色发丝，下方有深色褶皱织物，背景全黑。","analysis":"构图极度紧凑，几乎填满整个画面，环境占比极小。可见范围仅限于局部身体或物体表面，无法判断人物全身或具体姿态。视角为近距离俯视，光线昏暗，仅照亮红色区域，形成强烈的明暗对比。红色液体在表面形成不规则的网状纹理，质感湿润，与周围暗部形成层次。","prompt":"极度近距离的俯视视角，画面被大面积起伏的红色表面占据，表面覆盖着湿润的红色液体，形成不规则的网状和斑点状纹理，质感粘稠。左上角边缘可见少量黑色发丝垂落，下方边缘是深褐色的褶皱织物，纹理粗糙。背景完全隐没在黑暗中，光线微弱且集中，仅照亮红色区域，营造出压抑、潮湿且诡异的视觉氛围，色彩以暗红、深褐和黑色为主。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:19:48-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (1243).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.395,"observed_resolution":"normal","observation_limits":[],"id":"VP-32105b49c335f4ba","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-d2a7a5221d3aecde","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1268).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"灰暗浑浊的水面占据整个画面，两条裸露的人腿横向延伸，皮肤湿润反光，右侧伴有白色水花与波纹。","analysis":"画面采用横向构图，主体为两条并排的人腿，从左侧延伸至右侧，仅可见大腿至小腿部分，身体其余部分不可见。视角为俯视，光线柔和漫射，肤色呈暖褐色，与冷灰绿色的水体形成对比，右侧水花增加了画面的动态感。","prompt":"俯视视角的灰暗水面，两条裸露的人腿横向占据画面中心，皮肤呈现湿润的暖褐色光泽，腿部线条流畅，从左侧延伸至右侧。水体呈浑浊的灰绿色，右侧伴有白色的水花飞溅和涟漪波纹，光线柔和均匀，无强烈阴影，整体色调偏冷，营造出一种静谧而略带压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:19:48-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (1268).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.507,"observed_resolution":"normal","observation_limits":[],"id":"VP-38f3c991b559578f","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-5497ed4f5030686d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1265).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"一个盛有绿色液体的透明玻璃容器，放置在深色金属加热底座上，背景为模糊的窗框与室外光线。","analysis":"画面主体为占据中心位置的玻璃容器，内部充满明亮的黄绿色液体，液面呈现波动状。容器下方是厚实的深色金属底座，左下角可见黑色线缆。背景处于失焦状态，左侧有强烈的白色光斑，整体光线明亮，色彩以绿色和金属灰为主。","prompt":"一个透明玻璃容器盛满明亮的黄绿色液体，放置在深色金属加热底座上。容器内部液体呈现波动状，表面有反光。玻璃容器下方是厚实的金属底座，左下角有一根黑色线缆延伸。背景是模糊的窗框和室外环境，左侧有强烈的白色光斑。画面色彩以绿色和金属灰为主，光线明亮，焦点集中在玻璃容器及其内部的液体上，背景虚化。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:19:48-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (1265).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-a8b93e0af361f5ba","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-440ba2c09bc52a2f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1240).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"画面极暗，主体为一张沾满深红色液体的面部特写，人物头部低垂，双手抬起靠近嘴部，背景几乎全黑，仅右侧有一块模糊的浅色区域。","analysis":"构图极度紧凑，仅可见人物面部及抬起的双手，头部占据画面中心。视角为平视略俯，光线极弱，仅微弱侧光勾勒出额头、鼻梁及手部轮廓。深红色物质覆盖口鼻及手部，与周围大面积黑色阴影形成强烈对比，右侧浅色块提供微弱背景层次。","prompt":"极暗环境下的面部特写，人物头部低垂，面部及双手沾满深红色粘稠液体，双手抬起靠近嘴部，手指弯曲。微弱侧光仅照亮额头、鼻梁及手部轮廓，其余部分隐没在深重阴影中。背景几乎全黑，右侧有一块模糊的浅色圆形区域。画面色调阴冷压抑，红色物质在黑暗中呈现湿润质感，整体氛围极度压抑且充满视觉冲击力。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:19:48-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (1240).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.392,"observed_resolution":"normal","observation_limits":[],"id":"VP-b6dc61bcc4bf5b00","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-ca6560aa49286eed","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (1138).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"一名短发女性侧卧在铺着条纹床单的大床上，腹部盖着白色织物。床头柜上放着一盏绿色灯罩的台灯，左侧可见一扇关闭的白色房门。","analysis":"画面采用平视视角，构图横向展开。人物全身可见，呈侧卧姿态，头部靠在右侧枕头上，双腿向左延伸，脚部穿着黑色平底鞋。人物占据画面中右部，左侧留白给床头柜和台灯。光线柔和偏冷，室内照明均匀，没有强烈的明暗对比，整体色调偏向低饱和度的灰绿与米色。","prompt":"一名深色短发女性侧卧在宽大的双人床上，身穿浅灰色短袖衬衫和短裤，腹部覆盖着一块白色方形织物。她头部枕在右侧的条纹枕头上，身体舒展，双腿伸直指向左侧，脚上穿着黑色平底鞋。床铺占据画面下半部分，铺着淡粉色与白色相间的条纹床单。画面左侧是一个深色床头柜，上面放置着一盏台灯，灯罩呈绿色半透明状，印有模糊的人脸图案。背景是带有竖条纹的浅色壁纸，最左侧边缘可见一扇关闭的白色房门及金属门把手。室内光线柔和均匀，色彩饱和度较低，呈现出一种安静、私密的卧室氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T01:19:48-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (1138).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.518,"observed_resolution":"normal","observation_limits":[],"id":"VP-4efb31a70ef8c542","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-5bd7f3bbb3c506cc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (1243).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"一张极度贴近的人脸特写，面部皮肤呈现苍白色，表面覆盖着大量鲜红色的斑驳液体，一只眼睛清晰可见，嘴巴张开，背景完全隐没在黑暗中。","analysis":"画面采用极端的特写构图，人物面部几乎填满了整个画幅，仅能看到一只眼睛、部分鼻梁和张开的嘴部，无法判断身体姿态。光线昏暗，主要光源似乎来自前方，照亮了面部中央，使得苍白的皮肤与鲜红的液体形成强烈对比。红色液体在光线下呈现出湿润的反光质感，周围大面积的阴影增强了画面的压抑感和视觉冲击力。","prompt":"一张极度贴近的人脸特写，画面主体是一张苍白的面孔，面部皮肤上覆盖着大量鲜红色的斑驳液体，呈现出湿润且粘稠的质感。人物的一只眼睛清晰可见，瞳孔在昏暗的光线下显得深邃，嘴巴张开，露出部分牙齿。光线主要集中在面部中央，使得苍白的皮肤与红色的液体形成强烈的视觉对比，周围大面积的阴影将背景完全隐没，营造出一种极度压抑、恐怖且充满张力的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:41:44+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (1243).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.44,"observed_resolution":"normal","observation_limits":[],"id":"VP-82b8932f2882bc1c","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-dfc0c6c5b73d78d9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (1268).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"一名短发人物浸泡在浴缸中，身体大部分被乳白色液体覆盖，仅露出头部和左臂，背景为深色边缘。","analysis":"画面采用高角度俯视构图，人物位于画面左侧，右侧大面积留白给浴缸内的液体。人物头部和左肩清晰可见，身体其余部分隐没在浑浊的乳白色液体中，仅能隐约看到胸部的轮廓。光线柔和且偏暗，整体色调低沉，液体表面平滑，与深色背景形成对比。","prompt":"高角度俯视镜头，一名留着黑色短发的人物浸泡在浴缸中。人物头部位于画面左侧，双眼低垂，神情平静，左臂弯曲抬起，手部靠近头部后方。身体大部分被乳白色的浑浊液体覆盖，液体表面平滑，隐约可见胸部轮廓。浴缸边缘呈浅色，背景为深黑色，光线昏暗柔和，整体色调偏冷，营造出一种静谧且略带压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:41:50+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (1268).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.502,"observed_resolution":"normal","observation_limits":[],"id":"VP-46eed45462fed9d7","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-78bdf65b33fee8bb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (1265).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"一名卷发男子位于画面中央，身穿深色外套，手捂嘴部，眼神向上凝视。背景为虚化的石砌建筑与窗户，左侧可见砖墙边缘，整体呈现户外街道环境。","analysis":"画面采用中心构图，人物占据主要视觉空间，仅可见头部及肩部以上。背景建筑处于焦外，形成虚实对比。光线从右上方照射，在人物面部左侧及头发边缘形成高光，右侧处于阴影中，明暗对比强烈。色彩以冷调的灰蓝背景与暖调的皮肤、发色形成层次，景深极浅，焦点锁定在人物眼部。","prompt":"一名留着深棕色中长卷发的男子，面部轮廓清晰，蓝色眼睛向上方凝视，神情专注。他身穿深色翻领外套，内搭浅色衣物，右手抬起捂住嘴部，手指自然弯曲。背景是模糊的灰色石砌建筑，可见多扇白色窗框的窗户，左侧边缘有红砖墙体。阳光从右上方照射，在人物面部和头发上形成明亮的高光，背景处于阴影中，整体色调偏冷，具有强烈的电影质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:41:58+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (1265).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.502,"observed_resolution":"normal","observation_limits":[],"id":"VP-20c7a0ac6969ec29","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-2e03f293f1d765eb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (1233).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"一名深色皮肤男性的面部特写，占据画面右侧大部分区域，背景左侧为模糊的明亮窗户结构。","analysis":"画面采用极近距离的侧面构图，人物面部占据右侧约三分之二，左侧留白给背景。光线从左侧窗户射入，形成强烈的侧光效果，照亮鼻梁、颧骨及眼角，而面部右侧及后脑勺则隐没在深沉的阴影中。背景虚化严重，仅能辨识出窗户的横向线条和冷色调的室外光线，与前景人物的暖色调皮肤形成对比。","prompt":"一张极度特写的男性面部侧面照片，人物为深色皮肤，面向左侧。画面构图紧凑，人物面部占据右侧大部分空间，左侧背景为模糊的窗户，透出冷白色的室外光线。强烈的侧光从左侧打入，勾勒出鼻梁、眉骨和眼窝的立体轮廓，皮肤纹理清晰可见，鼻翼处有一颗明显的黑痣。面部右侧及后脑部分处于深重阴影中，明暗对比强烈。背景虚化，隐约可见建筑物的横向线条，整体色调偏冷，营造出一种沉静、凝视的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:42:05+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (1233).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.54,"observed_resolution":"normal","observation_limits":[],"id":"VP-19f7fc9c8e691e8c","origin":"visual"},{"work_id":"src-da0a57939468ad5f","frame_id":"FG-144dd12948cc17f2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (1125).jpg","source_page":"https://film-grab.com/2013/08/29/trouble-every-day/","scene":"昏暗的室内角落，一名穿皮夹克的男子与一名短发女子面对面站立，男子双手抬起握住女子手腕，两人额头几乎相抵，背景可见金属柜门与粗糙墙面。","analysis":"画面主体为两人上半身，占据画面中心及左侧大部分区域。男子位于右侧，女子位于左侧，两人身体紧密接触。光线昏暗，主要光源似乎来自左前方，照亮了女子的面部和手臂，以及男子皮夹克的纹理。背景处于阴影中，右侧可见垂直的管道或柱状结构，墙面质感粗糙。","prompt":"昏暗室内场景，画面中心是一男一女两名人物上半身特写。右侧男子身穿深棕色皮夹克，深色卷发，侧脸面向左侧，双手抬起握住左侧女子的手腕，两人额头几乎相抵，姿态亲密且充满张力。左侧女子留着深色短发，身穿浅色吊带上衣，面部朝向右侧，神情凝重。背景左侧是深灰色的金属储物柜门，右侧是粗糙的土黄色墙面和垂直的管道结构。整体光线低沉，色调偏冷，阴影浓重，营造出压抑、紧张的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:42:12+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (1125).jpg","observed_dimensions":[1024,548],"source_thumbnail_dimensions":[500,268],"source_image_match_mae":0.468,"observed_resolution":"normal","observation_limits":[],"id":"VP-88bee8bb0907c281","origin":"visual"}]};